{
  "units": [
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "condition",
      "meaning": "In order for a private, nonprofit entity to be considered an eligible entity for purposes of section 9902(1) of this title, the entity must administer the community services block grant program through a tripartite board that is described in paragraph (2) and that fully participates in the development, planning, implementation, and evaluation of the program to serve low-income communities."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F003"],
      "kind": "requirement",
      "meaning": "The members of the tripartite board of the private nonprofit entity must be selected by the entity."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F003", "F005"],
      "kind": "requirement",
      "meaning": "The tripartite board of the private nonprofit entity must be composed so as to assure that one-third of the members of the board are elected public officials holding office on the date of selection, or their representatives."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F003", "F005"],
      "kind": "exception",
      "meaning": "For the tripartite board of a private nonprofit entity, if the number of elected officials holding office on the date of selection who are reasonably available and willing to serve on the board is less than one-third of the board's membership, membership of appointive public officials or their representatives may be counted toward meeting the one-third requirement."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F003", "F005"],
      "kind": "requirement",
      "meaning": "The tripartite board of the private nonprofit entity must be composed so as to assure that not fewer than one-third of the members are persons chosen in accordance with democratic selection procedures adequate to assure that these members are representative of low-income individuals and families in the neighborhood served."
    },
    {
      "quote_ref": "F009",
      "scope_refs": ["F003", "F005"],
      "kind": "requirement",
      "meaning": "Each representative of low-income individuals and families selected under clause (i) to represent a specific neighborhood within a community on the private nonprofit entity's tripartite board must reside in the neighborhood represented by that member."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F003", "F005"],
      "kind": "requirement",
      "meaning": "The tripartite board of the private nonprofit entity must be composed so as to assure that the remainder of the members are officials or members of business, industry, labor, religious, law enforcement, education, or other major groups and interests in the community served."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "condition",
      "meaning": "In order for a public organization to be considered an eligible entity for purposes of section 9902(1) of this title, the entity must administer the community services block grant program through either a tripartite board satisfying the requirements of paragraph (1) or another mechanism specified by the State under paragraph (2)."
    },
    {
      "quote_ref": "F013:F016",
      "scope_refs": ["F012"],
      "kind": "alternative",
      "meaning": "Under the tripartite board alternative for a public organization, the board members must be selected by the organization and the board must be composed so as to assure that not fewer than one-third of the members are persons chosen in accordance with democratic selection procedures adequate to assure that they are representative of low-income individuals and families in the neighborhood served, reside in the neighborhood served, and are able to participate actively in the development, planning, implementation, and evaluation of programs funded under this chapter."
    },
    {
      "quote_ref": "F018",
      "scope_refs": ["F012"],
      "kind": "alternative",
      "meaning": "Under the alternative mechanism for a public organization, the program must be administered through another mechanism specified by the State to assure decisionmaking and participation by low-income individuals in the development, planning, implementation, and evaluation of programs funded under this chapter."
    },
    {
      "quote_ref": "F019:F027",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Historical enactment citations, editor notes, and prior statutory provisions relating to earlier omitted or transferred sections 9910, 9910a, 9910b, 9910c, and 9910d, which contain no operative legal requirements or rights."
    }
  ]
}
